#!/bin/sh
# Stop the pre-edges WireGuard setup and move its files to /root/wireguard.pre-edges-<time>/.
# Files generated by edges are left alone, so this is safe to re-run. Run as root.
set -e
MARK="# edges: generated"
BACKUP=/root/wireguard.pre-edges-$(date +%Y%m%d-%H%M%S)
[ -d /etc/wireguard ] || exit 0
for f in /etc/wireguard/*; do
    [ -f "$f" ] || continue
    head -n 1 "$f" | grep -q "^$MARK" && continue
    case $f in
        *.conf)
            iface=$(basename "$f" .conf)
            systemctl disable --now "wg-quick@$iface" 2>/dev/null || true
            ip link del "$iface" 2>/dev/null || true
            ;;
    esac
    mkdir -p -m 700 "$BACKUP"
    mv "$f" "$BACKUP/"
    echo "moved $f -> $BACKUP/"
done
